add('Metadata, overview, components',[1,30],['2016 base game, 4–6 players, James Kniffen, no play-time figure in the supplied texts; BGG ID accepted from the assignment identity rather than external lookup.','Cooperative city operation with independent secret rivals, possible Federalist, multiple winners.','Ten districts/three tiers, five resource types, credits distinct from capital, Root outside city/districts, tracks and component counts.','Fourth android replacement only; components finite; reserve shortages prevent placement, removed pieces reusable.','FAQ > corrected print; RR > LTP; explicit RR golden rule for assets. Introductory setup/preset hands expressly outside scope.'],['RR p2 Golden Rules; §§8,10,12,20,23,48,49,64,67,69','LTP pp2–3,15 credits','FAQ Errata, Other'])
add('Complete setup',[31,44],['Deck separation and shuffling; setup card placements and turn count; setup cards returned to box.','Round 1, supply 0, top demand targets; corporation side by player count; faceup matching emergency; random active corporation.','Starting capital 10,11,12… clockwise; sheet draws; participating rivals plus Federalist, extra under board, secrecy, unused rival return.','Two investments, keep one facedown, rejected one facedown on top; reserve. No essential normal-setup step omitted.'],['RR p2 Complete Setup steps1–12; §§12.3,21.1,29,40,53'])
add('Corporation draw panels/contracts',[45,60],['All six corporations, both player-count sides, top-to-bottom order, exact fixed quantities/types and all General entries checked.','General chooses one previously undrawn type per entry without preview; Melange three entries use three types; 4-player General vs 5/6 fixed second type.','Globalsec 1/enemy removed; Haas 2 for movement at most once/turn; Jinteki 2/illness removed; Melange 3 if entire event threat rise <2; NBN 1/stage decrease; Weyland 2/outage removed.','Non-Melange action-only contracts, resolver irrelevant, movement not removal, Root does not trigger district removal, no NBN payout for outage-cleared unrest.'],['RR §§3.1,5,11–12,29,35,47','FAQ Contracts','corporation-sheets-face.jpg and corporation-sheets-back.jpg: all six used cells on each side; native manifest entries29–40'])
add('Rounds, active turn, production, event',[62,93],['Six standard rounds; demand after each pair; Action→Production→Event; active-player continuity; variable number of turns, possible no turn for a player.','Start-turn triggers before Refresh, ready then draw, one deal, optional End of Turn once/ability in chosen order including newly gained asset, hand-size discard then token left.','Action Phase ends only at end of a turn with no turn-track assets; full final end-of-turn step preserved.','Android districts ascending; produce then unrest, Human First +2/outage even if no production; no illness from exploitation.','Event top→bottom, upper effect then all listed placements then next turn count; rightmost turn-track reveal later; event bottomed; round advanced; sixth event turn reset unnecessary.','Warnings on card backs, public backs/secret looked-at fronts, Root spill threat, Melange whole-event check.'],['RR §§3–4,6.6,18.5,24–27,31,44,51,55,67,68','LTP pp6–9','FAQ Illness, Contracts'])
add('Event upper effects',[94,115],['All 16 printed event upper effects checked, including exact numerical thresholds and tier conditions, mutually exclusive Helium-3 branches, highest-numbered-first movement, Activist Cells move twice.','Lower-half placement lists and next-turn counts intentionally delegated to actual printed cards; generic required placement/turn-track procedure retained. No false claim that upper threat is entire event threat.'],['event-cards-face.jpg all16 used cells, fully covered by native manifest entries23–26','RR §§24–25,35–36; FAQ Contracts'])
add('Demand rounds',[117,126],['Investment scored before demand; each resource-sector investment zero if its own demand missed.','Every resource must meet target; one printed failure increase, not separate penalty per shortage; reset every supply including surplus; old demand bottomed and new targets.','All investments returned/shuffled then two drawn/one kept/other returned top; third demand ends after Pay Demand, last two steps omitted; immediate threat ending still controls.'],['RR §§17–18,28,33,58,62–63,69','LTP p9','FAQ Investments'])
add('Deal and support',[128,138],['All five deal steps; rightmost asset revealed/read aloud; mandatory main offer from hand or faceup emergency.','Exactly one clockwise counteroffer opportunity per nonactive player; discard count equals existing faceup counteroffers; new offer topmost and replaces current counterer; duplicate card permitted; active requires explicit ability.','Skip Support if no counteroffer; otherwise only nonactive/noncountering players; displaced counterers eligible; one clockwise opportunity each, one or more hand cards, one side only; no emergency support.','Most facedown support cards wins, tie main; resolve winning offer then claim asset; discard all played ordinary actions facedown; return every proposed emergency to original logo owner with winner facedown, others faceup.'],['RR §§1–4,14–16,21,34,37,59–60','LTP p10','FAQ Deals'])
add('Trading and emergency general rules',[140,161],['At-any-time trade/gift of capital and assets; binding immediate complete two-party or simultaneous multiplayer trade; future promise and disputed binding status nonbinding.','Corrected prohibited list includes investments; explicit card-directed giving/stealing/swapping distinguished from voluntary trade.','Exhausted traded assets remain exhausted; no claim effect from receiving by trade.','Emergency outside hand, faceup offer eligibility, winner facedown, losing/superseded faceup, original owner return after theft; hand theft/discard and support restrictions.','All six emergency printed effects, exact quantities, actors, order, side effects, optional up-to amounts and Mandatory Quarantine illness exemption checked.'],['RR §§6,9,21,26,30,65','LTP p14','FAQ Errata, Trading','emergency-cards-face.png all6 used faces; native manifest entries27–28'])
add('Ordinary actions',[163,190],['All20 distinct printed actions checked across five types, five copies each, including exact actor choices, up-to quantities, costs, sequencing, placement destinations, credit-zero branch, support bonuses, production modifiers, illness exemptions, local Caprice exception.','Arrest Orders, Riot Control, Scorched Earth preserve their printed X-to-Y text; no invented universal cost-feasibility restriction or invented trigger stack is imposed.','Liquidation ignores orgcrime but retains other production modifiers and explicit strike instruction; FAQ says not exploitation.'],['action-deck-1/2/5/6/7-face.png all100 used printed cells; native manifest entries0–14','RR §§2.9,5,43; FAQ Action Cards'])
add('Assets',[192,233],['All34 printed asset procedures checked: every timing, optional may, exhaustion/discard cost, recipient, resource/capital/card quantity, ownership condition, hand-size change, declaration requirement, give/steal/swap distinction and hidden-information handling.','End of Turn optional once/ability; same-owner choice, different owners clockwise from active; no extra universal resolution stack.','Chief Gorman status/cost nonrefund and printed further-counteroffer ban; Fall Guy immediate Support and Gorman exemption.','Isabel support status; Locust hand-only restriction; Naoko sequential when-claim resolution; Sunny separate increase instances; Thomas swap occurrence public.','Braintrust doubles each listed draw quantity, Floyd adds5 hand size, Toshiyuki no hand-size discard that turn; Bryan keeps stolen emergency state and excludes unused corporations.'],['asset-cards-face.jpg all34 used cells; native manifest entries15–20','RR §§2.9,6,9,15.8,21.6,22,26,30,56,61','FAQ Asset Cards, Thomas Haas'])
add('Investments',[235,254],['All12 printed investments checked, including every formula, cap and count threshold. Five sectors use actual supply, require that sector demand met, not all demand met.','Banking/Entertainment min(6,2+S); Energy min(7,3+2S); Retail min(6,2+2S); Technology min(6,3+S).','Illness/orgcrime/Human First2→3,3→5,4+→7; prisec1→3,2→6,3+→8; outage1→3,2→5,3+→7; Short Sale low resource-type counts1→3,2→5,3+→7; Populist per protest/strike district.','City counts exclude reserve/Root, no listed award below thresholds; no investment trading.'],['investment-cards-face.jpg all12 used cells; native manifest entries21–22','RR §§8,18,33; FAQ Investments, Errata'])
add('Capital, rivals, ending',[257,272],['Capital token40-side wrapping and flipping back; bright five-spaces have no effect.','Immediate stop at25 threat; final third demand after Pay Demand; reveal rivals; ordinary named rival strict greater, ties lose; self rival beat2 others in4-player,3 in5/6.','Below25 Federalist loses; at25 every ordinary player loses and Federalist requires at least25 capital; possible no Federalist/all lose/multiple ordinary winners.','Federalist cannot defer immediate ending for investment score; final failure occurs after investment already scored. No highest-overall requirement.'],['RR §§7,18.2,18.6,28,50,63,69; LTP pp9,15'])
add('Production, unrest, outage interaction',[274,301],['Primary circle/leftmost vs secondary; one-resource district has no secondary; protest normal, strike/outage zero all; development+1 primary only; orgcrime zero primary even if developed; secondary survives.','Card-directed production applies modifiers unless explicit exemption; tracks cap, zero cannot be reduced; production before exploitation unrest.','Stable→protest→strike and reverse with token changes; capped ordinary increase no outage.','Human First stable→strike, protest/strike/outage triggers outage placement; existing outage new outage moves; outage clears unrest without NBN payout; removal leaves stable.'],['RR §§19,27,31,38–39,41,43–45,52,54,57–58,68; FAQ Contracts'])
add('Placement, movement, illness',[303,317],['Per-district maxima for all listed components; enemy identity and prisec displacement, not removal.','Placement from reserve; incoming duplicate enemy/illness/outage follows exiting arrows to higher district, repeat until room or Root; district10→Root; each Root arrival returned to reserve and+2.','Movement out not removal, no removal contract at Root; androids ignore paths, individually move into unoccupied android destinations; unrest/development do not move.','Illness action-only+2 total; district chosen/involved movement/placement/removal, including prevented attempted placement/movement and reserve shortage; explicit local illness exemption; no event/exploitation trigger.'],['RR §§5,8,10–11,19–20,23,27,31–32,35–42,47–48,63,68; FAQ Illness'])
add('Assets/discards/hidden information and final references',[319,365],['Gaining faceup vs claim; exhausted retention, refresh timing; discard asset facedown bottom; theft/giving/swapping precise destinations and public secrecy.','Shared action discard always facedown, no inspection; exhaustion of requested deck triggers entire shared discard shuffle/reveal/sort and per-type shuffle into existing decks.','Action hand identities cannot be told, counts cannot be lied about; rival secrecy; turn-track secrecy; investment deck secrecy; event fronts secret/backs public.','FAQ/rulings table checked against entire official FAQ and relevant RR exceptions; condensed Player Reference agrees with preceding operative rules. No essential core procedure omission identified.'],['RR §§2,6,9,15.8,21–22,24.3,26,30,33,50,56,61; LTP pp10,14; complete FAQ'])
